{
  "explanation": "The 68-95-99.7 rule (empirical rule) describes how data spreads in a normal distribution: roughly 68% of values lie within 1 standard deviation of the mean, 95% within 2σ, and 99.7% within 3σ. These nested bands are a quick way to reason about probability without integrating the density. Drag the mean or use the slider to explore how the shaded regions stay centered on μ.",
  "manimCode": "const ax = new Axes({
  xRange: [-4, 4, 1],
  yRange: [0, 0.5, 0.1],
  xLength: 11,
  yLength: 4.2,
  tips: false
});
ax.moveTo([0, -0.3, 0]);

const pdf = (x, mu, s) => (1 / (s * Math.sqrt(2 * Math.PI))) * Math.exp(-0.5 * ((x - mu) / s) ** 2);

let mu = 0;
const sigma = 1;

let curve = ax.plot(x => pdf(x, mu, sigma), { color: WHITE, xRange: [-4, 4], numSamples: 400 });

function makeBand(lo, hi, color, opacity) {
  const area = ax.getArea(ax.plot(x => pdf(x, mu, sigma), { xRange: [lo, hi], numSamples: 200 }), [lo, hi], { color, opacity });
  return area;
}

let band3 = makeBand(mu - 3 * sigma, mu + 3 * sigma, BLUE_E, 0.25);
let band2 = makeBand(mu - 2 * sigma, mu + 2 * sigma, BLUE_C, 0.35);
let band1 = makeBand(mu - 1 * sigma, mu + 1 * sigma, BLUE_A, 0.5);

function sigmaLine(k, col) {
  const x = mu + k * sigma;
  const top = pdf(x, mu, sigma);
  const line = new Line({
    start: ax.c2p(x, 0),
    end: ax.c2p(x, top + 0.02),
    color: col
  });
  line.setStrokeWidth(2);
  return line;
}

let lines = [];
function rebuildLines() {
  for (const L of lines) scene.remove(L);
  lines = [];
  const specs = [
    [-3, GRAY], [-2, TEAL], [-1, YELLOW],
    [0, WHITE],
    [1, YELLOW], [2, TEAL], [3, GRAY]
  ];
  for (const [k, col] of specs) {
    const L = sigmaLine(k, col);
    lines.push(L);
    scene.add(L);
  }
}

const title = new Text({ text: '68–95–99.7 Rule (Empirical Rule)', color: WHITE, fontSize: 32 });
title.moveTo([0, 3.4, 0]);

let pct68 = new Text({ text: '68% within 1σ', color: BLUE_A, fontSize: 22 });
pct68.moveTo([-4.2, 2.6, 0]);
let pct95 = new Text({ text: '95% within 2σ', color: BLUE_C, fontSize: 22 });
pct95.moveTo([-4.2, 2.1, 0]);
let pct997 = new Text({ text: '99.7% within 3σ', color: BLUE_E, fontSize: 22 });
pct997.moveTo([-4.2, 1.6, 0]);

function tickLabel(k, latex) {
  const t = new MathTex({ latex });
  return t;
}

const labM = new MathTex({ latex: '\\mu' });
await labM.waitForRender();
labM.scale(0.7);
labM.moveTo(ax.c2p(mu, -0.06));

const labL1 = new MathTex({ latex: '\\mu-\\sigma' });
await labL1.waitForRender();
labL1.scale(0.55);
labL1.moveTo(ax.c2p(mu - sigma, -0.06));

const labR1 = new MathTex({ latex: '\\mu+\\sigma' });
await labR1.waitForRender();
labR1.scale(0.55);
labR1.moveTo(ax.c2p(mu + sigma, -0.06));

const labL2 = new MathTex({ latex: '\\mu-2\\sigma' });
await labL2.waitForRender();
labL2.scale(0.5);
labL2.moveTo(ax.c2p(mu - 2 * sigma, -0.12));

const labR2 = new MathTex({ latex: '\\mu+2\\sigma' });
await labR2.waitForRender();
labR2.scale(0.5);
labR2.moveTo(ax.c2p(mu + 2 * sigma, -0.12));

const labL3 = new MathTex({ latex: '\\mu-3\\sigma' });
await labL3.waitForRender();
labL3.scale(0.5);
labL3.moveTo(ax.c2p(mu - 3 * sigma, -0.06));

const labR3 = new MathTex({ latex: '\\mu+3\\sigma' });
await labR3.waitForRender();
labR3.scale(0.5);
labR3.moveTo(ax.c2p(mu + 3 * sigma, -0.06));

const meanDot = new Dot({ point: ax.c2p(mu, 0), color: YELLOW });
meanDot.scale(1.2);

scene.add(ax, band3, band2, band1, curve, title, pct68, pct95, pct997);
scene.add(labM, labL1, labR1, labL2, labR2, labL3, labR3, meanDot);
rebuildLines();

function rebuildAll() {
  scene.remove(band3, band2, band1, curve);
  curve = ax.plot(x => pdf(x, mu, sigma), { color: WHITE, xRange: [-4, 4], numSamples: 400 });
  band3 = makeBand(mu - 3 * sigma, mu + 3 * sigma, BLUE_E, 0.25);
  band2 = makeBand(mu - 2 * sigma, mu + 2 * sigma, BLUE_C, 0.35);
  band1 = makeBand(mu - 1 * sigma, mu + 1 * sigma, BLUE_A, 0.5);
  scene.add(band3, band2, band1, curve);
  rebuildLines();

  labM.moveTo(ax.c2p(mu, -0.06));
  labL1.moveTo(ax.c2p(mu - sigma, -0.06));
  labR1.moveTo(ax.c2p(mu + sigma, -0.06));
  labL2.moveTo(ax.c2p(mu - 2 * sigma, -0.12));
  labR2.moveTo(ax.c2p(mu + 2 * sigma, -0.12));
  labL3.moveTo(ax.c2p(mu - 3 * sigma, -0.06));
  labR3.moveTo(ax.c2p(mu + 3 * sigma, -0.06));
  meanDot.moveTo(ax.c2p(mu, 0));

  // keep curve and labels on top
  scene.remove(curve, meanDot, labM, labL1, labR1, labL2, labR2, labL3, labR3);
  scene.add(curve, meanDot, labM, labL1, labR1, labL2, labR2, labL3, labR3);
  for (const L of lines) { scene.remove(L); scene.add(L); }
}

const controls = new Controls(scene, { position: 'bottom-right', width: 260 });
controls.addSlider({
  label: 'Mean (μ)',
  min: -1.5,
  max: 1.5,
  value: 0,
  step: 0.1,
  onChange: (v) => {
    mu = v;
    rebuildAll();
  }
});

controls.addButton({
  label: 'Reset μ = 0',
  onClick: () => {
    mu = 0;
    rebuildAll();
  }
});

// subtle legend bars
const leg1 = new Rectangle({ width: 0.35, height: 0.2, color: BLUE_A });
leg1.setFill(BLUE_A, 0.8);
leg1.moveTo([-5.6, 2.6, 0]);
const leg2 = new Rectangle({ width: 0.35, height: 0.2, color: BLUE_C });
leg2.setFill(BLUE_C, 0.8);
leg2.moveTo([-5.6, 2.1, 0]);
const leg3 = new Rectangle({ width: 0.35, height: 0.2, color: BLUE_E });
leg3.setFill(BLUE_E, 0.8);
leg3.moveTo([-5.6, 1.6, 0]);
scene.add(leg1, leg2, leg3);

makeHoverable(band1, scene, { hoverOpacity: 0.75, cursor: 'pointer' });
makeHoverable(band2, scene, { hoverOpacity: 0.55, cursor: 'pointer' });
makeHoverable(band3, scene, { hoverOpacity: 0.4, cursor: 'pointer' });

await scene.wait(999999);"
